import React, { PropsWithChildren, useMemo } from 'react';

import { HoneycombColorMetadataContext } from '../context/honeycomb-color-metadata.context.js';
import { useBuildColorMetadata } from '../hooks/use-build-color-metadata.js';
import { useHoneycombData } from '../hooks/use-honeycomb-data.js';

export const HoneycombColorMetadataProvider = ({
  children,
}: PropsWithChildren) => {
  const data = useHoneycombData();
  const colorMetadata = useBuildColorMetadata(data);

  const providerValue = useMemo(
    () => ({
      tileData: data,
      colorMetadata,
    }),
    [data],
  );

  return (
    <HoneycombColorMetadataContext.Provider value={providerValue}>
      {children}
    </HoneycombColorMetadataContext.Provider>
  );
};
